using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct CharacterId : IEquatable<CharacterId>, IComparable<CharacterId>
    {
        public Guid Value { get; }

        public CharacterId(Guid value)
        {
            Value = value;
        }

        public static CharacterId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static CharacterId NewRandom() => new CharacterId(Guid.NewGuid());

        public static CharacterId Parse(string text) => new CharacterId(Guid.Parse(text));

        public static bool TryParse(string text, out CharacterId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new CharacterId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(CharacterId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is CharacterId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(CharacterId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(CharacterId left, CharacterId right) => left.Equals(right);

        public static bool operator !=(CharacterId left, CharacterId right) => !left.Equals(right);
    }
}
